const paths={calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16M8 14h2m4 0h2M8 17h2',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3m5 3h4',home:'M3 10 12 3l9 7v10H5V10m4 10v-7h6v7',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m4 5-2.5 5.5L8 16l2.5-5.5L16 8',habit:'M6 4h12v16H6zM9 9h6M9 13l2 2 4-4',book:'M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1v15',chart:'M4 20V10m7 10V4m7 16v-7M2 21h20',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',heart:'M12 20S2 14 3 8c1-5 7-5 9 0 2-5 8-5 9 0 1 6-9 12-9 12',briefcase:'M3 7h18v13H3zM8 7V4h8v3M3 12c6 4 12 4 18 0M12 12v4',wallet:'M3 6h17v14H3zM3 6V3h14v3m-2 7h6v4h-6z',people:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-1a3 3 0 1 0 0-6M2 21v-3c0-6 12-6 12 0v3m2-7c4 0 6 2 6 5v2',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l3 2',leaf:'M20 3c-12-1-18 4-15 12 6 5 16-1 15-12M3 21l13-13',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8',check:'m5 12 4 4L19 6',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',play:'m8 5 11 7-11 7z',edit:'m4 16 12-12 4 4L8 20H4v-4',flame:'M12 2c1 6 7 7 7 13 0 9-14 9-14 0 0-3 3-6 3-6s-1 5 2 5c4-1 2-8 2-12'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
let reminders,calendarMonth=today().slice(0,7);
let state=fresh(),storageBlocked=false,rawRecovery='',selectedDay=today(),route='hoy',toastTimer,focusMinutes=25,focusTaskId='',statsDays=30,statsFilter='all';
const fmt=(day,opts={day:'numeric',month:'long'})=>new Intl.DateTimeFormat('es-PE',{...opts,timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'));
function restoreTimer(t){if(!t||typeof t!=='object')return null;if(!/^[\w-]{1,80}$/.test(t.id)||!['focus','break'].includes(t.mode)||!validDate(t.day)||!Number.isFinite(t.total)||t.total<1000||t.total>MAX_DURATION_SECONDS*1000||!Number.isFinite(t.remaining)||t.remaining<0||t.remaining>t.total||typeof t.running!=='boolean'||!Number.isFinite(t.endAt)||typeof t.taskId!=='string')return null;return {id:t.id,mode:t.mode,day:t.day,total:t.total,remaining:t.remaining,running:t.running,endAt:t.endAt,taskId:t.taskId};}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);state=validateBackup(parsed);state.timer=restoreTimer(parsed.timer);}}catch(e){storageBlocked=true;try{rawRecovery=localStorage.getItem(KEY)||'';}catch{}showStorageWarning('No pudimos leer tus datos. No se sobrescribirá el contenido anterior. Descarga una copia para recuperarlo.');}
try{if(!storageBlocked&&ensureGoalColors(state))localStorage.setItem(KEY,JSON.stringify(state));}catch{showStorageWarning('No se pudieron guardar los colores de las metas. Descarga un respaldo antes de salir.');}
function showStorageWarning(message){const w=$('#storage-warning');w.hidden=false;w.innerHTML=`${esc(message)} <button class="button ghost" data-action="export">Descargar copia</button>`;}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function commit(change,message){if(storageBlocked){notify('Primero recupera o importa tus datos desde Ajustes.');return false;}const next=structuredClone(state);change(next);ensureGoalColors(next);try{localStorage.setItem(KEY,JSON.stringify(next));state=next;reminders?.sync();$('#save-status').textContent='Guardado en este navegador';if(message)notify(message);return true;}catch{showStorageWarning('No se pudo guardar. El navegador puede tener el almacenamiento lleno o desactivado. Exporta tus datos antes de salir.');notify('No se guardó el cambio. Tus datos anteriores se conservan.');return false;}}
function heading(eyebrow,title,copy,button=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${copy}</p></div>${button}</div>`;}
const btn=(action,text,extra='',kind='')=>`<button type="button" class="button ${kind}" data-action="${action}" ${extra}>${text}</button>`;
function empty(title,copy,action,label,ico='leaf'){return `<div class="empty"><div class="empty-symbol">${icon(ico)}</div><h3>${title}</h3><p>${copy}</p>${action?btn(action,label):''}</div>`;}
function stat(value,label,ico){return `<div class="stat"><div class="stat-icon">${icon(ico)}</div><div><span class="stat-value">${value}</span><span class="stat-label">${label}</span></div></div>`;}
function areaTag(key){const a=AREAS[key]||AREAS.personal;return `<span class="tag" style="color:${a.color}"><i></i>${a.name}</span>`;}
function goalOptions(selected=''){return `<option value="">Sin meta vinculada</option>${state.goals.map(g=>`<option value="${g.id}" ${g.id===selected?'selected':''}>${esc(g.title)}</option>`).join('')}`;}
function areaOptions(selected='personal'){return Object.entries(AREAS).map(([k,a])=>`<option value="${k}" ${k===selected?'selected':''}>${a.name}</option>`).join('');}
function dayPicker(){return `<label class="day-picker">Día de registro <input type="date" id="day-picker" value="${selectedDay}" max="${today()}" aria-label="Día de registro"></label>`;}
function renderWeek(){const start=weekStart(selectedDay);return `<div class="week">${Array.from({length:7},(_,i)=>{const day=shiftDay(start,i);return `<button class="day ${day===selectedDay?'selected':''}" data-action="pick-day" data-day="${day}" aria-label="${fmt(day)}" aria-pressed="${day===selectedDay}">${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'][i]}<b>${Number(day.slice(-2))}</b><i></i></button>`;}).join('')}</div>`;}
function renderTask(t){
 const g=state.goals.find(g=>g.id===t.goalId),day=t.occurrenceDay||t.date,repeat=repetitionText(t.repeatDays),future=day>today();
 return `<div class="task ${t.status==='done'?'done':''}"><button class="check ${t.status==='done'?'done':''}" data-action="toggle-task" data-id="${t.id}" data-day="${day}" ${future?'disabled':''} aria-label="${t.status==='done'?'Reabrir':'Completar'} ${esc(t.title)}" aria-pressed="${t.status==='done'}">${t.status==='done'?'✓':''}</button><div class="task-info"><div class="task-title">${esc(t.title)}</div><div class="meta">${g?`<span class="goal-tag" style="--goal-color:${g.color}"><i></i>${esc(g.title)}</span>`:'<span>Personal</span>'}${t.startTime?`<span class="task-time">${timeLabel(t.startTime)}${t.reminder&&t.reminder!=='off'?' · '+(t.reminder==='alarm'?'Alarma':'Aviso'):''}</span>`:''}<span>· ${formatDuration(taskDurationSeconds(t))}</span>${repeat?`<span class="repeat-tag">↻ ${repeat}</span>`:''}${future?'<span>Próxima: '+fmt(day,{day:'numeric',month:'short'})+'</span>':day<selectedDay&&t.status!=='done'?'<span class="priority">Pendiente del '+fmt(day,{day:'numeric',month:'short'})+'</span>':''}${t.priority===3?'<span class="priority">Prioridad</span>':''}</div></div><div class="task-actions"><button class="icon-button" data-action="focus-task" data-id="${t.id}" aria-label="Concentrarme en ${esc(t.title)}">${icon('play')}</button><button class="icon-button" data-action="edit-task" data-id="${t.id}" data-day="${day}" aria-label="Editar ${esc(t.title)}">⋯</button></div></div>`;
}

function renderHabit(h,large=false){const eligible=habitScheduled(h,selectedDay)&&selectedDay<=today(),count=habitValue(h,selectedDay),target=targetAt(h,selectedDay),done=habitDone(h,selectedDay),days=streak(h,selectedDay);const row=`<div class="habit-row ${!eligible?'rest':''} ${done?'complete':''}"><div class="habit-icon">${icon(done?'check':AREAS[h.area].icon)}</div><div class="habit-info"><div class="habit-title">${esc(h.title)}</div><div class="meta">${!eligible?'Descanso · ':''}${large?`${esc(h.unit)} · `:''}${count} de ${target} <span>·</span> ${days} ${days===1?'día':'días'} de racha${h.weekDays?.length<7?' · '+repetitionText(h.weekDays):''}</div></div><div class="counter"><button data-action="habit-minus" data-id="${h.id}" ${!count||!eligible?'disabled':''} aria-label="Restar ${h.step} a ${esc(h.title)}">−</button><span>${done?'✓':count}</span><button data-action="habit-plus" data-id="${h.id}" ${!eligible?'disabled':''} aria-label="Sumar ${h.step} a ${esc(h.title)}">+</button></div>${large?`<button class="icon-button" data-action="edit-habit" data-id="${h.id}" aria-label="Editar ${esc(h.title)}">⋯</button>`:''}</div>`;return large?`<div class="card habit-large">${row}<div class="mini-history" aria-label="Últimos 14 días">${Array.from({length:14},(_,i)=>{const d=shiftDay(selectedDay,i-13);return `<span class="${habitDone(h,d)?'complete':habitValue(h,d)?'partial':''}" title="${d}: ${habitValue(h,d)} / ${targetAt(h,d)}"></span>`;}).join('')}</div></div>`:row;}
function clockTime(seconds){return msToClockString(seconds*1000,true,true).padStart(8,'0');}
function selectedFocusSeconds(){const task=state.tasks.find(t=>t.id===focusTaskId);return task?taskDurationSeconds(task):focusMinutes*60;}
function timerDisplay(){return clockTime(Math.ceil((state.timer?timerRemaining(state.timer):selectedFocusSeconds()*1000)/1000));}
function timerElapsed(){return clockTime(Math.floor(Math.max(0,state.timer.total-timerRemaining(state.timer))/1000));}
function focusCard(full=false){
 const timer=state.timer,task=state.tasks.find(t=>t.id===(timer?timer.taskId:focusTaskId));
 return `<section class="card focus-card"><div class="section-head"><h2>${icon('clock')} Un espacio para enfocarte</h2>${!full?'<a class="text-button" href="#enfoque">Abrir ›</a>':''}</div><p class="eyebrow">${timer?.mode==='break'?'RESPIRA. TAMBIÉN ES PARTE DEL CAMINO.':'UNA COSA A LA VEZ'}</p><div class="timer" id="timer-display" role="timer" aria-label="Tiempo restante">${timerDisplay()}</div><p class="subcopy" id="timer-description">${esc(task?.title||(timer?.mode==='break'?'Descanso breve':timer?'Sesión de concentración':'Un poco de atención puede cambiar tu día.'))}</p>${timer?`<div class="timer-detail"><span>Transcurrido <b id="timer-elapsed">${timerElapsed()}</b></span><span>Duración <b>${clockTime(timer.total/1000)}</b></span></div>`:task?`<p class="subcopy">Duración de la tarea: ${formatDuration(taskDurationSeconds(task))}</p>`:''}${!timer?`${full?`<select id="focus-task-select" aria-label="Tarea de la sesión"><option value="">Concentración libre</option>${state.tasks.filter(t=>t.status!=='done'||isRepeating(t)||t.id===focusTaskId).map(t=>`<option value="${t.id}" ${t.id===focusTaskId?'selected':''}>${esc(t.title)} · ${formatDuration(taskDurationSeconds(t))}</option>`).join('')}</select>`:''}${!task?`<select id="focus-duration" aria-label="Duración de la sesión">${[15,25,50].map(n=>`<option value="${n}" ${n===focusMinutes?'selected':''}>${n} minutos de concentración</option>`).join('')}</select>`:''}`:''}<div class="timer-controls">${!timer?btn('start-focus',icon('play')+' Comenzar sesión'):btn(timer.running?'pause-focus':'resume-focus',timer.running?'Pausar':'Continuar')}${timer?btn('finish-focus','Terminar','','ghost'):btn('start-break','Descansar 5 min','','ghost')}</div>${timer?'<p class="subcopy timer-note">El tiempo se conserva al recargar. Al llegar a cero se registra tu sesión. Puedes marcar la tarea como completada en tu plan.</p>':''}</section>`;
}
function weekdayPicker(days,scope='task'){
 return `<fieldset class="weekday-picker" data-scope="${scope}"><legend>${scope==='task'?'Repetir los días':'Días del hábito'}</legend><div class="weekday-buttons">${WEEKDAYS.map((name,i)=>`<button type="button" class="weekday-choice ${days.includes(i)?'selected':''}" data-action="toggle-weekday" data-value="${i}" aria-label="${name}" aria-pressed="${days.includes(i)}"><span>${['L','M','X','J','V','S','D'][i]}</span><small>${name.slice(0,3)}</small></button>`).join('')}</div><div class="repeat-caption"><span data-repeat-summary>${days.length?'Cada '+days.map(d=>WEEKDAYS[d].toLowerCase()).join(', '):'Una sola vez, en la fecha elegida.'}</span>${scope==='task'?'<button type="button" class="text-button" data-action="clear-weekdays">Solo una vez</button>':''}</div></fieldset>`;
}
function selectedWeekdays(form){return [...form.querySelectorAll('.weekday-choice[aria-pressed="true"]')].map(b=>Number(b.dataset.value));}
function repetitionText(days){return days?.length?days.length===7?'Todos los días':days.map(d=>WEEKDAYS[d].slice(0,3)).join(' · '):'';}
function goalTaskView(task){if(!isRepeating(task))return taskOccurrence(task,task.date);for(let i=0;i<14;i++){const day=shiftDay(selectedDay,i);const hit=taskOccurrences({tasks:[task]},day,day)[0];if(hit)return hit;}return taskOccurrence(task,selectedDay);}
function flameCard(){
 const displayDay=selectedDay,days=activityStreak(state,displayDay),{completed,total,ratio,allCompleted}=flameTaskProgress(state,displayDay),level=ratio>=.8?'green':ratio>=.4?'yellow':'red';
 return `<section class="flame-card" aria-label="Llama de constancia"><div class="flame-art"><div class="flame-mount" role="img" aria-label="Llama azul y naranja. A mitad de tus tareas y hábitos alcanza el nivel intermedio; al completarlos todos brilla con su máxima fuerza." data-completed="${completed}" data-total="${total}" data-progress="${ratio.toFixed(4)}"></div><span class="flame-size-label">${completed} de ${total} ${total===1?'actividad completada':'actividades completadas'}</span></div><div class="flame-copy"><p class="eyebrow">TU CONSTANCIA TIENE VIDA</p><h2>${days?days+' '+(days===1?'día':'días')+' de racha':'Enciende tu constancia'}</h2><p>Completa tus tareas y hábitos del día para encender tu llama con su máxima fuerza.</p><div class="flame-progress"><span class="status-dot ${level}"></span><b>${allCompleted?'100% · ¡Llama al máximo!':Math.round(ratio*100)+'% de tus tareas y hábitos completados'}</b><span>· ${fmt(displayDay,{day:'numeric',month:'short'})}</span></div><a href="#progreso" class="text-button">Ver mis estadísticas ›</a><small>A mitad del plan alcanza el nivel intermedio; al completar todas las tareas y hábitos, su luz y energía llegan al máximo. La racha cuenta días activos; los días de descanso no la interrumpen.</small></div></section>`;
}
function completionChart(days=7,end=today()){
 const start=shiftDay(end,1-days),points=Array.from({length:days},(_,i)=>{const day=shiftDay(start,i),counts=dayProgress(state,day);return {day,score:counts.ratio,planned:counts.total};});
 const x=i=>45+i*570/Math.max(1,days-1),y=score=>155-score*125;
 let path='',previous=false;for(let i=0;i<points.length;i++){const point=points[i];if(!point.planned){previous=false;continue;}path+=`${previous?'L':'M'}${x(i).toFixed(1)},${y(point.score).toFixed(1)} `;previous=true;}
 const id='completion-gradient-'+days;
 return `<div class="completion-chart"><svg viewBox="0 0 650 194" role="img" aria-label="Cumplimiento de tareas y hábitos de los últimos ${days} días: rojo de 0 a 39%, amarillo de 40 a 79%, verde desde 80%"><defs><linearGradient id="${id}" gradientUnits="userSpaceOnUse" x1="0" y1="155" x2="0" y2="30"><stop offset="0" stop-color="var(--danger)"/><stop offset=".5" stop-color="var(--warning)"/><stop offset="1" stop-color="var(--success)"/></linearGradient></defs>${[0,.5,1].map(value=>`<path d="M45 ${y(value)}H615" class="chart-grid"/><text x="32" y="${y(value)+4}" text-anchor="end">${Math.round(value*100)}%</text>`).join('')}<path d="${path}" fill="none" stroke="url(#${id})" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round"/>${points.map((p,i)=>p.planned?`<circle cx="${x(i)}" cy="${y(p.score)}" r="${days>7?3:5}" fill="${p.score>=.8?'var(--success)':p.score>=.4?'var(--warning)':'var(--danger)'}" stroke="var(--card)" stroke-width="2"><title>${fmt(p.day)}: ${Math.round(p.score*100)}% de ${p.planned} actividades</title></circle>`:'').join('')}${points.map((p,i)=>i===0||i===days-1||days<=7||i%Math.ceil(days/6)===0?`<text x="${x(i)}" y="183" text-anchor="middle">${fmt(p.day,{day:'numeric',month:'short'})}</text>`:'').join('')}</svg></div><div class="completion-legend"><span><i class="red"></i>Rojo: menos del 40%</span><span><i class="yellow"></i>Amarillo: 40–79%</span><span><i class="green"></i>Verde: 80–100%</span></div>${!points.some(p=>p.planned)?'<p class="subcopy chart-empty">La línea aparecerá al programar tus primeras tareas o hábitos. Los días sin plan no cuentan como fallos.</p>':''}`;
}
function statusDistribution(summary){
 const c=2*Math.PI*53,total=summary.total,done=total?summary.done/total*c:0,pending=total?summary.pending/total*c:0,deleted=total?summary.deleted/total*c:0;
 return `<div class="distribution"><svg viewBox="0 0 150 150" role="img" aria-label="${summary.done} completadas, ${summary.pending} pendientes y ${summary.deleted} eliminadas"><circle cx="75" cy="75" r="53" class="donut-base"/>${[[done,0,'var(--success)'],[pending,done,'var(--warning)'],[deleted,done+pending,'var(--danger)']].map(([value,offset,color])=>value?`<circle cx="75" cy="75" r="53" fill="none" stroke="${color}" stroke-width="13" stroke-dasharray="${value} ${c-value}" stroke-dashoffset="${-offset}" transform="rotate(-90 75 75)"/>`:'').join('')}<text x="75" y="75" text-anchor="middle" class="donut-value">${total}</text><text x="75" y="94" text-anchor="middle">tareas</text></svg><div class="distribution-labels"><p><i class="green"></i> Completadas <b>${summary.done}</b></p><p><i class="yellow"></i> Pendientes <b>${summary.pending}</b></p><p><i class="red"></i> Eliminadas <b>${summary.deleted}</b></p></div></div>`;
}
function home(){
 const tasks=taskOccurrences(state,selectedDay,selectedDay).filter(t=>t.status!=='deleted').sort((a,b)=>(a.status==='done')-(b.status==='done')||b.priority-a.priority);
 const hs=state.habits.filter(h=>habitScheduled(h,selectedDay)),overdue=dueTasks(state,selectedDay).filter(t=>t.date<selectedDay);
 const summary=taskSummary(state,selectedDay,selectedDay),counts=dayProgress(state,selectedDay),name=state.profile.name?`, ${esc(state.profile.name.split(' ')[0])}`:'';
 return heading('TU DÍA, A TU MANERA',`Este es tu día${name}.`,'Organiza tus actividades y sigue tu constancia.',btn('new-task',icon('plus')+' Nueva tarea'))+flameCard()+`
 <section class="card day-tasks" aria-labelledby="day-tasks-title">
 <div class="section-head"><h2 id="day-tasks-title">Tareas del día</h2><label class="day-picker">Fecha <input type="date" id="home-day-picker" value="${selectedDay}" aria-label="Fecha del plan del día"></label></div>
 <div class="stats daily-stats">${stat(summary.done,'Tareas completadas','check')}${stat(summary.pending,'Tareas pendientes','clock')}${stat(summary.deleted,'Tareas eliminadas','trash')}</div>
 <p class="metrics-note">Solo tareas de ${fmt(selectedDay)}. Las tareas vinculadas a metas cuentan una sola vez.</p>
 <div class="day-task-list">${tasks.length?tasks.map(renderTask).join(''):empty('No hay tareas para este día','Añade una tarea o elige otra fecha para ver su plan.','new-task','Añadir una tarea','compass')}</div>
 <button class="add-row" data-action="new-task"><span>+</span><span>Añadir una tarea o actividad repetida</span></button>
 </section>
 <div class="home-grid"><div>
 <section class="card day-plan" aria-labelledby="day-plan-title"><div class="section-head"><h2 id="day-plan-title">Plan del día</h2><button class="text-button" data-action="plan">Ayúdame a priorizar ›</button></div>${renderWeek()}
 <p class="day-completion" data-day-progress="${counts.ratio.toFixed(4)}">Cumplimiento del día: <b>${Math.round(counts.ratio*100)}%</b> · ${counts.completed} de ${counts.total} tareas y hábitos.</p>
 <p class="subcopy">Este porcentaje es el mismo que alimenta la flama. Solo cuenta lo programado para ${fmt(selectedDay,{day:'numeric',month:'short'})}.</p>
 <div class="section-head"><h3>Hábitos del día</h3><a href="#habitos" class="text-button">Ver todos ›</a></div>${hs.length?hs.map(h=>renderHabit(h)).join(''):empty('No hay hábitos programados para esta fecha','Los días de descanso no bajan tu cumplimiento.','new-habit','Crear un hábito','leaf')}
 </section>
 ${overdue.length?`<section class="card overdue-tasks"><details><summary>Pendientes de otros días · ${overdue.length}</summary><p class="subcopy">Se conservan para que puedas retomarlos. No cambian la flama ni el porcentaje de la fecha seleccionada.</p>${overdue.map(renderTask).join('')}</details></section>`:''}
 </div><div class="right-col"><section class="card"><div class="section-head"><h2>Tu cumplimiento</h2><a href="#progreso" class="text-button">Estadísticas ›</a></div><p class="subcopy">Tareas y hábitos de los 7 días hasta ${fmt(selectedDay,{day:'numeric',month:'short'})}.</p>${completionChart(7,selectedDay)}</section>${focusCard()}<section class="card"><div class="section-head"><h2>Hacia dónde vas</h2><a href="#rumbo" class="text-button">Mis metas ›</a></div>${state.goals.length?state.goals.slice(0,3).map(g=>`<div style="margin:18px 0"><div class="row-link"><h3 style="font-size:12px">${esc(g.title)}</h3><span class="meta">${Math.round(progress(state,g.id)*100)}%</span></div><div class="progress-track" style="margin-top:10px"><span style="width:${progress(state,g.id)*100}%"></span></div></div>`).join(''):empty('Conecta tus actividades con una meta','Así podrás ver cuánto avanzas con cada paso.','new-goal','Definir mi primera meta','target')}</section></div></div>`;
}

function goalsPage(){return heading('DALE DIRECCIÓN A TUS DÍAS','Tu vida, con rumbo.','Conecta tus acciones de hoy con lo que quieres construir.',btn('new-goal',icon('plus')+' Nueva meta'))+(!state.goals.length?`<div class="card">${empty('Todo camino empieza con una intención','Define qué quieres cambiar, por qué te importa y cuál será tu primer paso.','new-goal','Crear mi primera meta','compass')}</div>`:`<div class="goal-grid">${state.goals.map(g=>{const tasks=state.tasks.filter(t=>t.goalId===g.id&&t.status!=='deleted'&&!t.archivedOn).map(goalTaskView),p=progress(state,g.id);return `<section class="card goal-card" style="--goal-color:${g.color}"><div class="goal-top">${areaTag(g.area)}<button class="icon-button" data-action="edit-goal" data-id="${g.id}" aria-label="Editar ${esc(g.title)}">⋯</button></div><h2>${esc(g.title)}</h2><p>${esc(g.why||'Cada pequeño paso cuenta.')}</p><p class="goal-dates">${fmt(goalStart(g),{day:'numeric',month:'short',year:'numeric'})}${g.deadline?' → '+fmt(g.deadline,{day:'numeric',month:'short',year:'numeric'}):' · Sin fecha de fin'}<b>${goalTimeLabel(g)}</b></p><div class="progress-track"><span style="width:${p*100}%"></span></div><div class="progress-meta"><span>${tasks.some(t=>t.recurring)?'Cumplimiento de actividades':tasks.filter(t=>t.status==='done').length+' de '+tasks.length+' pasos'}</span><span>${Math.round(p*100)}%${g.deadline?' · '+fmt(g.deadline,{day:'numeric',month:'short'}):''}</span></div><div class="goal-task-list">${tasks.length?tasks.map(renderTask).join(''):'<p class="subcopy">Añade el primer paso para comenzar.</p>'}</div><button class="add-row" data-action="new-task" data-goal="${g.id}"><span>+</span><span>Añadir un paso</span></button></section>`;}).join('')}</div>`)+`<div class="templates"><p>¿Necesitas un punto de partida?</p>${[['salud','Cuidar mi salud'],['aprendizaje','Aprender algo nuevo'],['finanzas','Ordenar mis finanzas']].map(([key,label])=>`<button class="template" data-action="template" data-key="${key}">${label} ›</button>`).join('')}</div>`;}
function habitsPage(){const hs=state.habits.filter(h=>h.created<=selectedDay);return heading('EL PODER DE LO COTIDIANO','Un poco, todos los días.','Selecciona qué días de la semana quieres practicar cada hábito.',btn('new-habit',icon('plus')+' Nuevo hábito'))+dayPicker()+(hs.length?hs.map(h=>renderHabit(h,true)).join(''):`<section class="card">${empty('Hazlo pequeño. Hazlo tuyo.','Leer una página, caminar diez minutos o tomar un vaso de agua. Tú eliges el inicio.','new-habit','Crear mi primer hábito','leaf')}</section>`)+`<p class="subcopy">Las rachas cuentan los días programados en los que alcanzaste tu objetivo. Tus días de descanso no rompen la racha.</p>`;}
function journalPage(){const j=state.journal.find(j=>j.day===selectedDay);return heading('UN MOMENTO PARA TI','Escúchate un poco.','Reconoce lo que salió bien y lo que necesitas para mañana.')+dayPicker()+`<div class="journal-layout"><form id="journal-form" class="card"><h2 style="margin-bottom:23px">Tu registro del día</h2><label class="field">¿Cómo te sentiste?<select name="mood">${['Muy difícil','Un poco difícil','En calma','Bien','Muy bien'].map((v,i)=>`<option value="${i+1}" ${(j?.mood||3)===i+1?'selected':''}>${['😔','😕','😐','🙂','😊'][i]} ${v}</option>`).join('')}</select></label><label class="field">Tu nivel de energía<select name="energy">${['Muy baja','Baja','Media','Alta','Muy alta'].map((v,i)=>`<option value="${i+1}" ${(j?.energy||3)===i+1?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">¿Qué pequeño logro quieres reconocer?<textarea name="wins" maxlength="5000" placeholder="Incluso haberlo intentado cuenta…">${esc(j?.wins||'')}</textarea></label><label class="field">¿Qué tienes en mente?<textarea name="notes" maxlength="5000" placeholder="Algo que aprendiste, agradeces o quieres cambiar…">${esc(j?.notes||'')}</textarea></label><div class="form-actions"><button class="button" type="submit">Guardar mi reflexión</button></div></form><section class="card"><h2 style="margin-bottom:8px">Mirar atrás también ayuda</h2><p class="subcopy">Tus reflexiones más recientes.</p>${state.journal.length?[...state.journal].sort((a,b)=>b.day.localeCompare(a.day)).slice(0,7).map(e=>`<article class="journal-entry"><div class="row-link"><h3>${fmt(e.day)}</h3><button class="text-button" data-action="pick-day" data-day="${e.day}">Abrir ›</button></div><p>${esc(e.wins||e.notes||'Un momento para reconocer cómo me siento.')}</p></article>`).join(''):empty('Este espacio es tuyo','Tus reflexiones aparecerán aquí cuando guardes tu primer registro.',null,'','book')}</section></div>`;}
function activityBreakdown(){
 const days=Array.from({length:7},(_,i)=>shiftDay(today(),i-6)),counts=days.map(d=>taskSummary(state,d,d).done),max=Math.max(1,...counts);
 return `<div class="home-grid"><section class="card"><h2>Completadas por día</h2><div class="weekly-bars">${days.map((d,i)=>`<div class="weekly-bar"><span>${counts[i]}</span><i style="height:${counts[i]/max*100}%"></i><small>${fmt(d,{weekday:'short'})}</small></div>`).join('')}</div></section><section class="card"><h2>Progreso por área de vida</h2>${Object.entries(AREAS).map(([key,area])=>{const goals=state.goals.filter(g=>g.area===key),score=objectiveProgress(goals.map(g=>({progress:progress(state,g.id)})));return `<div class="bar-row"><span>${area.name}</span><div class="progress-track"><span style="width:${score*100}%;background:${area.color}"></span></div><span>${goals.length?Math.round(score*100)+'%':'—'}</span></div>`;}).join('')}</section></div>`;
}
function progressPage(){
 const now=today(),start=shiftDay(now,1-statsDays),summary=taskSummary(state,start,now),seconds=state.sessions.filter(s=>s.day>=start&&s.day<=now).reduce((a,s)=>a+sessionSeconds(s),0);
 const activity=activitySummary(state,start,now);
 const p=objectiveProgress(state.goals.map(g=>({progress:progress(state,g.id)}))),days=calendarDays(now,14),flat=[];for(let c=0;c<14;c++)for(let r=0;r<7;r++)flat.push(days[r][c]);
 const filtered=summary.items.filter(t=>statsFilter==='all'||t.status===statsFilter).sort((a,b)=>b.date.localeCompare(a.date));
 return heading('TUS DATOS, A LA VISTA','Tus estadísticas.','Completadas, pendientes y eliminadas: cada fecha de una actividad repetida cuenta por separado.',`<label class="stats-range">Período<select id="stats-range" aria-label="Período de estadísticas">${[7,30,90].map(n=>`<option value="${n}" ${statsDays===n?'selected':''}>Últimos ${n} días</option>`).join('')}</select></label>`)+`<div class="stats">${stat(summary.done,'Tareas completadas','check')}${stat(summary.pending,'Tareas pendientes','clock')}${stat(summary.deleted,'Tareas eliminadas','trash')}</div><div class="home-grid"><section class="card"><div class="section-head"><h2>La línea de tu cumplimiento</h2><b class="rate-label">${Math.round(activity.ratio*100)}% de tareas y hábitos completados</b></div><p class="subcopy">Rojo, amarillo y verde según el porcentaje diario de tareas y hábitos cumplidos. Los días de descanso no se penalizan.</p>${completionChart(statsDays)}</section><section class="card"><h2>Estado de tus tareas</h2>${statusDistribution(summary)}<p class="subcopy">${fmt(start)} – ${fmt(now)}. Se cuenta cada actividad según su fecha programada.</p></section></div><div class="stats secondary-stats">${stat(activityStreak(state,now)+' días','Racha de actividad','flame')}${stat(formatDuration(seconds),'Concentración en el período','clock')}${stat(Math.round(p*100)+'%','Avance medio de tus metas','target')}</div>${activityBreakdown()}<section class="card"><div class="section-head"><h2>Historial de actividades</h2><select id="stats-filter" aria-label="Filtrar historial">${[['all','Todas'],['done','Completadas'],['todo','Pendientes'],['deleted','Eliminadas']].map(([key,label])=>`<option value="${key}" ${statsFilter===key?'selected':''}>${label}</option>`).join('')}</select></div>${filtered.length?`<div class="activity-history">${filtered.slice(0,50).map(t=>`<div class="history-row"><span class="history-status ${t.status}">${icon(t.status==='done'?'check':t.status==='deleted'?'trash':'clock')}</span><div><b>${esc(t.title)}</b><small>${fmt(t.date)}${t.repeatDays?.length?' · '+repetitionText(t.repeatDays):''}</small></div><span class="status-label ${t.status}">${{done:'Completada',todo:'Pendiente',deleted:'Eliminada'}[t.status]}</span>${t.status==='deleted'?`<button type="button" class="text-button" data-action="restore-task" data-id="${t.id}" data-day="${t.date}">Restaurar</button>`:''}</div>`).join('')}</div>${filtered.length>50?'<p class="subcopy">Mostrando las 50 actividades más recientes. Usa un período más corto para ver el detalle.</p>':''}`:empty('Aún no hay registros en este período','Programa actividades para empezar a ver tus datos reales.',null,'','chart')}<p class="history-note">Las tareas eliminadas se conservan desde esta actualización. Las que se borraron definitivamente antes no pueden reconstruirse.</p></section><section class="card"><div class="section-head"><h2>Mapa de constancia</h2><span class="meta">Últimas 14 semanas</span></div><div class="heatmap-wrap"><div class="heatmap" aria-label="Calendario de constancia">${flat.map(d=>`<span class="${d>now?'future':''}" data-level="${dayScore(state,d)?Math.max(1,Math.ceil(dayScore(state,d)*4)):0}" title="${fmt(d)}: ${Math.round(dayScore(state,d)*100)}%"></span>`).join('')}</div></div><div class="legend">Menos <i style="background:var(--heat-empty)"></i><i></i><i style="background:var(--heat-two)"></i><i style="background:var(--heat-three)"></i><i></i> Más</div></section>`;
}

function focusPage(){return heading('PROTEGE TU ATENCIÓN','Ahora, solo esto.','Un espacio sin prisa para dedicarte a una cosa importante.')+`<div class="focus-page">${focusCard(true)}<section class="card"><h2>Sesiones recientes</h2>${state.sessions.length?[...state.sessions].reverse().slice(0,10).map(s=>`<div class="session"><span>${fmt(s.day,{day:'numeric',month:'short'})} · ${esc(state.tasks.find(t=>t.id===s.taskId)?.title||'Concentración libre')}</span><b>${formatDuration(sessionSeconds(s))}</b></div>`).join(''):empty('Tu atención también es progreso','Aquí se registra tu tiempo de enfoque, incluidos los segundos.',null,'','clock')}</section></div>`;}
function render(){route=location.hash.slice(1)||'hoy';if(!['hoy','calendario'].includes(route)&&selectedDay>today())selectedDay=today();if(!['hoy','calendario','rumbo','habitos','diario','progreso','enfoque'].includes(route))route='hoy';$('#navigation').innerHTML=[['hoy','Hoy','home'],['calendario','Calendario','calendar'],['rumbo','Mi rumbo','compass'],['habitos','Hábitos','habit'],['diario','Diario','book'],['progreso','Estadísticas','chart']].map(([key,name,i])=>`<a href="#${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(i)}<span>${name}</span></a>`).join('');$('#date-label').textContent=fmt(today(),{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('.avatar').textContent=state.profile.name?state.profile.name.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase():'PV';$('#content').innerHTML=({hoy:home,calendario:calendarPage,rumbo:goalsPage,habitos:habitsPage,diario:journalPage,progreso:progressPage,enfoque:focusPage}[route])();const flameDay=selectedDay>today()?today():selectedDay;livingFlame.mount(document.querySelector('.flame-mount'),{day:flameDay,...flameTaskProgress(state,flameDay)});document.title=({hoy:'Hoy',calendario:'Calendario',rumbo:'Mi rumbo',habitos:'Hábitos',diario:'Diario',progreso:'Mi progreso',enfoque:'Enfoque'}[route])+' · Proyecto de vida';}
function timeLabel(time){if(!validTime(time))return '';const [h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'a. m.':'p. m.'}`;}
function goalTimeLabel(goal,day=today()){const t=goalTiming(goal,day);if(t.phase==='upcoming')return `Empieza en ${t.days} ${t.days===1?'día':'días'}`;if(t.phase==='finished')return `Terminó hace ${t.days} ${t.days===1?'día':'días'}`;return t.days===null?'En camino · sin fecha de fin':t.days===0?'Termina hoy':`Faltan ${t.days} ${t.days===1?'día':'días'} para terminar`;}
function reminderPanelContent(){
 const status=reminders?.getStatus()||{native:!!window.proyectoAndroid?.reminders,permission:'loading'};
 if(!status.native)return `<p class="reminder-note">En la web los avisos funcionan mientras la página está abierta. Para avisos con la aplicación cerrada, usa el APK de Android.</p>${status.permission==='default'?btn('enable-reminders','Activar avisos del navegador','','secondary'):status.permission==='denied'?'<p class="reminder-note">Los avisos están bloqueados en los ajustes de este navegador.</p>':''}`;
 if(status.error)return `<p class="reminder-note">No pudimos actualizar los avisos. Tus rutinas siguen guardadas.</p>${btn('reminder-settings','Revisar ajustes de Android','','secondary')}`;
 if(status.permission==='loading')return '<p class="reminder-note">Comprobando los avisos de Android…</p>';
 if(status.permission!=='granted')return `<p class="reminder-note">Activa las notificaciones para que tus rutinas puedan avisarte con la aplicación cerrada.</p>${btn(status.permission==='prompt'?'enable-reminders':'reminder-settings',status.permission==='prompt'?'Activar avisos':'Permitir avisos en Android','','secondary')}`;
 return `<p class="reminder-note">${status.scheduledCount||0} ${status.scheduledCount===1?'rutina con aviso':'rutinas con aviso'}. Funcionan con la aplicación cerrada.${status.nextAt?' Próximo: '+new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(status.nextAt))+'.':''}</p>${!status.exact?`<p class="reminder-note">Android puede retrasar los avisos. Permite alarmas y recordatorios para usar la hora precisa.</p>${btn('exact-reminders','Permitir horarios precisos','','secondary')}`:'<p class="reminder-ready">✓ Horarios precisos activados</p>'}${status.alarmSound===false?'<p class="reminder-note">El canal de alarmas está silenciado. Puedes activar su sonido en Android.</p>':''}${btn('reminder-settings','Sonido y permisos de Android','','ghost')}`;
}
function calendarPage(){
 const cells=monthDays(calendarMonth),first=calendarMonth+'-01',last=shiftDay(shiftMonth(calendarMonth,1)+'-01',-1),monthGoals=state.goals.filter(g=>goalStart(g)<=last&&(!g.deadline||g.deadline>=first));
 const agenda=taskOccurrences(state,selectedDay,selectedDay).filter(t=>t.status!=='deleted').sort((a,b)=>(a.startTime||'99:99').localeCompare(b.startTime||'99:99')||b.priority-a.priority);
 const active=state.goals.filter(g=>goalOnDay(g,selectedDay));
 return heading('TU TIEMPO TIENE UN LUGAR','Tu calendario.','Mira qué toca cada día y cuánto falta para tus metas.',btn('new-task',icon('plus')+' Nueva rutina'))+`<div class="calendar-layout"><section class="card month-card"><div class="calendar-toolbar"><button class="icon-button" data-action="calendar-month" data-offset="-1" aria-label="Mes anterior">‹</button><h2>${fmt(first,{month:'long',year:'numeric'})}</h2><button class="icon-button" data-action="calendar-month" data-offset="1" aria-label="Mes siguiente">›</button>${btn('calendar-today','Hoy','','ghost')}</div><div class="month-weekdays" aria-hidden="true">${['L','M','X','J','V','S','D'].map(d=>`<span>${d}</span>`).join('')}</div><div class="month-grid" aria-label="Días de ${fmt(first,{month:'long',year:'numeric'})}">${cells.map(day=>{const goals=monthGoals.filter(g=>goalOnDay(g,day)),tasks=taskOccurrences(state,day,day).filter(t=>t.status!=='deleted');return `<button type="button" class="month-day ${day.slice(0,7)!==calendarMonth?'other-month':''} ${day===today()?'is-today':''} ${day===selectedDay?'selected':''}" data-action="calendar-day" data-day="${day}" aria-pressed="${day===selectedDay}" aria-label="${fmt(day,{day:'numeric',month:'long',year:'numeric'})}: ${tasks.length} rutinas, ${goals.length} metas"><b>${Number(day.slice(-2))}</b><span class="calendar-stripes">${goals.slice(0,4).map(g=>`<i style="background:${g.color}" data-goal-id="${g.id}" title="${esc(g.title)}"></i>`).join('')}${goals.length>4?`<small>+${goals.length-4}</small>`:''}</span><small class="calendar-task-count">${tasks.length?tasks.length+' '+(tasks.length===1?'rutina':'rutinas'):' '}</small></button>`;}).join('')}</div><p class="calendar-help">Cada franja de color representa una meta, desde su inicio hasta su fin. Toca un día para ver sus rutinas.</p><div class="calendar-goal-key">${monthGoals.length?monthGoals.map(g=>`<button class="calendar-key-item" data-action="edit-goal" data-id="${g.id}"><i style="background:${g.color}"></i><span><b>${esc(g.title)}</b><small>${fmt(goalStart(g),{day:'numeric',month:'short'})}${g.deadline?' → '+fmt(g.deadline,{day:'numeric',month:'short'}):' → Sin fecha de fin'} · ${goalTimeLabel(g)}</small></span></button>`).join(''):'<p class="subcopy">No hay metas en este mes. Crea una y elige sus fechas de inicio y fin.</p>'}</div></section><div class="calendar-agenda"><section class="card"><div class="section-head"><div><p class="eyebrow">${selectedDay===today()?'HOY':'DÍA SELECCIONADO'}</p><h2>${fmt(selectedDay,{weekday:'long',day:'numeric',month:'long'})}</h2></div>${btn('new-task','+ Rutina','','ghost')}</div>${agenda.length?agenda.map(renderTask).join(''):empty('Un día con espacio','Aquí aparecerán las rutinas programadas para esta fecha.','new-task','Programar una rutina','calendar')}<p class="subcopy">${agenda.length} ${agenda.length===1?'rutina programada':'rutinas programadas'}${agenda.filter(t=>t.startTime).length?' · Ordenadas por hora de inicio.':'.'}</p></section><section class="card"><h2>Metas en este día</h2>${active.length?active.map(g=>`<button class="calendar-goal-summary" style="--goal-color:${g.color}" data-action="edit-goal" data-id="${g.id}"><b>${esc(g.title)}</b><span>${goalTimeLabel(g,selectedDay)}</span></button>`).join(''):empty('Sin metas en esta fecha','Elige el inicio y el fin de tus metas para verlas en el calendario.','new-goal','Crear una meta','target')}</section><section class="card"><h2>${icon('bell')} Tus recordatorios</h2><div data-reminder-panel>${reminderPanelContent()}</div></section></div></div>`;
}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function field(name,label,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
const saveButtons=(label='Guardar')=>`<p class="form-error" id="form-error" role="alert"></p><div class="form-actions">${btn('close-modal','Cancelar','','ghost')}<button type="submit" class="button">${label}</button></div>`;
function goalModal(id=''){const g=state.goals.find(g=>g.id===id),color=g?.color||nextGoalColor(state.goals);modal(g?'Editar mi meta':'¿Qué quieres construir?',`<form id="goal-form" data-id="${id}">${field('title','Mi meta',g?.title||'','text','required maxlength="160" placeholder="Por ejemplo: volver a sentirme con energía"')}<label class="field">Área de mi vida<select name="area">${areaOptions(g?.area)}</select></label><label class="field">¿Por qué me importa?<textarea name="why" maxlength="1000" placeholder="Conecta esta meta con algo que tenga sentido para ti.">${esc(g?.why||'')}</textarea></label><div class="form-row">${field('startDate','Fecha de inicio',g?goalStart(g):today(),'date','required')}${field('deadline','Fecha de fin (opcional)',g?.deadline||'','date')}</div><div class="goal-color-picker"><input type="hidden" name="color" value="${color}"><span class="goal-color-swatch" style="background:${color}"></span><span>Tu color en el calendario</span>${btn('new-goal-color','Otro color','','ghost')}</div>${!g?field('firstStep','Mi primer paso (opcional)','','text','maxlength="160" placeholder="Una acción pequeña y concreta"'):btn('delete-goal','Eliminar meta',`data-id="${id}"`,'danger')}${saveButtons(g?'Guardar cambios':'Crear mi meta')}</form>`);}
function durationPicker(seconds){
 const parts=durationParts(seconds);
 return `<fieldset class="duration-picker"><legend>Duración de la actividad</legend><div class="duration-preview"><output id="task-duration-preview" aria-live="polite">${clockTime(seconds)}</output><span>horas : minutos : segundos</span></div>${[['hours','Horas',24],['minutes','Minutos',60],['seconds','Segundos',60]].map(([name,label,max])=>`<label class="duration-slider"><span>${label}<output data-duration-output="${name}">${parts[name]}</output></span><input type="range" name="${name}" min="0" max="${max}" step="1" value="${parts[name]}" aria-label="${label}" ${parts.hours===24&&name!=='hours'?'disabled':''}><span class="duration-limits"><small>0</small><small>${max}</small></span></label>`).join('')}<p class="duration-help">Desliza las barras con el dedo. Máximo 24 horas. El botón ▶ usará esta duración.</p></fieldset>`;
}
function updateDurationPicker(form){
 const sliders=[...form.querySelectorAll('.duration-slider input')];
 if(sliders.reduce((sum,input)=>sum+Number(input.value)*({hours:3600,minutes:60,seconds:1}[input.name]),0)>=MAX_DURATION_SECONDS){for(const input of sliders)input.value=input.name==='hours'?24:0;}
 const values=Object.fromEntries(sliders.map(input=>[input.name,Number(input.value)]));
 for(const input of sliders){input.disabled=values.hours===24&&input.name!=='hours';form.querySelector(`[data-duration-output="${input.name}"]`).textContent=input.value;}
 $('#task-duration-preview').textContent=clockTime(durationFromParts(values.hours,values.minutes,values.seconds));
 $('#form-error').textContent='';
}
function taskModal(id='',goalId='',occurrenceDay=''){
 const t=state.tasks.find(t=>t.id===id);
 modal(t?'Editar mi actividad':'Programar una actividad',`<form id="task-form" data-id="${id}" data-day="${occurrenceDay||t?.date||selectedDay}">${field('title','¿Qué voy a hacer?',t?.title||'','text','required maxlength="160" placeholder="Estudiar, trabajar, hacer ejercicio…"')}<label class="field">Conecta con una meta<select name="goalId">${goalOptions(t?.goalId||goalId)}</select></label><div class="form-row task-schedule">${field('date','Fecha de inicio',t?.date||selectedDay,'date','required')}${field('startTime','Hora de inicio',t?.startTime||'','time')}</div><fieldset class="reminder-picker"><legend>Recordatorio de esta rutina</legend><label class="field">Cómo avisarme<select name="reminder">${[['off','Sin recordatorio'],['notification','Notificación con sonido'],['alarm','Sonido de alarma']].map(([key,label])=>`<option value="${key}" ${(t?.reminder||'off')===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Cuándo avisarme<select name="reminderMinutes">${[0,5,10,15,30,60].map(n=>`<option value="${n}" ${(t?.reminderMinutes||0)===n?'selected':''}>${n?n+' minutos antes':'A la hora de inicio'}</option>`).join('')}</select></label><p class="subcopy">La hora indica cuándo empieza; la duración determina el cronómetro. Se repetirá en los días que elijas.</p><div data-reminder-panel>${reminderPanelContent()}</div></fieldset>${durationPicker(taskDurationSeconds(t))}${weekdayPicker(t?.repeatDays||[])}<label class="field">Prioridad<select name="priority">${[[1,'A mi ritmo'],[2,'Importante'],[3,'Mi prioridad']].map(([n,label])=>`<option value="${n}" ${(t?.priority||2)===n?'selected':''}>${label}</option>`).join('')}</select></label>${t&&isRepeating(t)?'<p class="dialog-note">La repetición se guarda por fecha. Cambiar el horario no borra lo que completaste antes.</p>':''}${t?btn('delete-task','Eliminar actividad',`data-id="${id}" data-day="${occurrenceDay||t.date}"`,'danger'):''}${saveButtons(t?'Guardar cambios':'Añadir a mi camino')}</form>`);
}

function habitModal(id=''){
 const h=state.habits.find(h=>h.id===id);
 modal(h?'Ajustar mi hábito':'Crear un hábito',`<form id="habit-form" data-id="${id}">${field('title','Mi hábito',h?.title||'','text','required maxlength="160" placeholder="Leer, caminar, beber agua…"')}<label class="field">Área de mi vida<select name="area">${areaOptions(h?.area)}</select></label>${weekdayPicker(h?.weekDays||ALL_DAYS,'habit')}<div class="form-row">${field('target','Objetivo por día programado',h?.target||1,'number','required min="1" max="1000000" step="1"')}${field('unit','Unidad',h?.unit||'veces','text','required maxlength="30" placeholder="vasos, páginas, minutos…"')}</div>${field('step','Cantidad por cada toque en +',h?.step||1,'number','required min="1" max="1000000" step="1"')}${h?'<p class="dialog-note">Los nuevos días y objetivos se aplican desde hoy. Tus registros anteriores se conservan.</p>'+btn('delete-habit','Eliminar hábito',`data-id="${id}"`,'danger'):''}${saveButtons(h?'Guardar cambios':'Crear mi hábito')}</form>`);
}

function settings(){modal('Tu espacio personal',`<form id="profile-form">${field('name','¿Cómo te llamas?',state.profile.name,'text','maxlength="60" placeholder="Tu nombre"')}<label class="field">¿Qué vida quiero construir?<textarea name="purpose" maxlength="1000" placeholder="Escribe una intención que quieras recordar cada día.">${esc(state.profile.purpose)}</textarea></label>${saveButtons('Guardar mi propósito')}</form><div class="settings-actions"><h3>Recordatorios de tus rutinas</h3><div data-reminder-panel>${reminderPanelContent()}</div><p class="dialog-note">Tus datos se guardan en este navegador. No hay cuenta ni sincronización entre dispositivos. Un respaldo te permite trasladarlos o recuperarlos.</p>${btn('export','Descargar mis datos ↓','','secondary')}${btn('import','Importar un respaldo','','ghost')}</div>`);}
function about(){modal('Un proyecto que crece contigo',`<p class="dialog-note">Proyecto de vida reúne metas, hábitos, concentración y reflexión en un espacio personal. Esta versión funciona en tu navegador y puede usarse sin conexión después de la primera carga.</p>${[['LifeOS','lifeos-app/lifeos','Progreso de metas y objetivos adaptado para datos locales.','MIT'],['Super Productivity','super-productivity/super-productivity','Formato de tiempo usado en las sesiones de concentración.','MIT'],['Beaver Habits','daya0576/beaverhabits','Calendario semanal del mapa de constancia, adaptado a JavaScript.','BSD-3-Clause'],['Neohabit','Vsein/Neohabit','Búsqueda de objetivos por fecha para conservar el historial de cada hábito.','AGPL-3.0']].map(([n,repo,what,license])=>`<div class="credit"><a href="https://github.com/${repo}" target="_blank" rel="noopener">${n} ›</a><small>${what}<br>${license}</small></div>`).join('')}<a class="source-link" href="https://github.com/lr6468031-ship-it/sinestesia-Visualizer/tree/main/proyecto-de-vida" target="_blank" rel="noopener">Código fuente completo y créditos ›</a><a class="source-link" href="LICENSE" target="_blank" rel="noopener">Licencia de esta aplicación: AGPL-3.0 ›</a><p class="dialog-note" style="margin-top:20px">No se conectan los servicios de los proyectos originales. Esta es una aplicación independiente con adaptaciones de herramientas concretas.</p>`);}
async function download(name,contents,type='application/json'){if(window.proyectoAndroid?.saveBackup)return (await window.proyectoAndroid.saveBackup({name,contents})).saved;const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);return true;}
async function exportData(){try{if(await download(`proyecto-de-vida-${today()}.json`,storageBlocked&&rawRecovery?rawRecovery:JSON.stringify(state,null,2)))notify(window.proyectoAndroid?'Respaldo guardado. Guárdalo en un lugar seguro.':'Respaldo descargado. Guárdalo en un lugar seguro.');}catch{notify('No se pudo guardar el respaldo. Inténtalo de nuevo y elige otra ubicación.');}}
function confirmDelete(kind,id,day=selectedDay){
 const labels={goal:'esta meta',task:'esta actividad',habit:'este hábito'},task=state.tasks.find(t=>t.id===id);
 const recurring=kind==='task'&&task&&isRepeating(task);
 modal('¿Eliminar '+labels[kind]+'?',`<p class="dialog-note">${kind==='goal'?'Las tareas vinculadas se conservarán como tareas personales.':kind==='habit'?'Se eliminarán también sus registros de hábitos. Puedes descargar un respaldo antes.':recurring?'Puedes quitar solo la fecha elegida o detener la repetición desde hoy. Lo completado antes se conserva en las estadísticas.':'La tarea saldrá de tu plan, pero quedará en las estadísticas como eliminada y podrás restaurarla.'}</p><div class="form-actions deletion-actions">${btn('close-modal','Cancelar','','ghost')}${recurring?btn('confirm-delete','Dejar de repetir',`data-kind="task" data-id="${id}" data-day="${today()}" data-series="true"`,'danger'):''}${btn('confirm-delete',recurring?'Solo el '+fmt(day,{day:'numeric',month:'short'}):'Eliminar',`data-kind="${kind}" data-id="${id}" data-day="${day}"`,'danger')}</div>`);
}

function startFocus(taskId='',mode='focus'){
 if(state.timer){location.hash='enfoque';notify('Ya tienes una sesión. Puedes pausarla o terminarla.');return;}
 const task=mode==='focus'?state.tasks.find(t=>t.id===(taskId||focusTaskId)):null;
 const seconds=mode==='break'?300:task?taskDurationSeconds(task):focusMinutes*60;
 if(commit(s=>{s.timer={id:uid(),mode,day:today(),total:seconds*1000,remaining:seconds*1000,running:true,endAt:Date.now()+seconds*1000,taskId:task?.id||''};})){if(mode==='focus')focusTaskId=task?.id||'';render();}
}
function finishTimer(early=false){
 if(!state.timer)return;
 const focus=state.timer.mode==='focus',seconds=Math.floor(Math.max(0,state.timer.total-timerRemaining(state.timer))/1000);
 const message=!focus?'Descanso terminado. Vuelve cuando quieras.':seconds<1?'Sesión terminada. Aún no transcurrió un segundo.':`${early?'Sesión terminada':'¡Tiempo completado!'} Se registraron ${formatDuration(seconds)} de enfoque.`;
 if(commit(s=>settleTimer(s,Date.now(),early),message))render();
}
function plan(){
 const list=planTasks(state,selectedDay);
 const content=list.length?'<p class="dialog-note">Estas son hasta tres tareas pendientes, ordenadas por prioridad y antigüedad, con un máximo de dos horas en total. Tú decides si este plan encaja contigo.</p>'+list.map(t=>`<div class="session"><span>${esc(t.title)}</span><b>${formatDuration(taskDurationSeconds(t))}</b></div>`).join('')+`<div class="form-actions">${btn('close-modal','Lo revisaré','','ghost')}${btn('apply-plan','Usar estas prioridades',`data-ids="${list.map(t=>t.id).join(',')}"`)}</div>`:empty('Tu día tiene espacio','Añade tareas de hasta dos horas para poder proponerte un plan.','new-task','Añadir una tarea','compass');
 modal('Un plan posible para tu día',content);
}
const templates={salud:{title:'Cuidar mi salud',why:'Tener más energía para disfrutar mi día.',steps:['Elegir un horario para caminar','Preparar una comida que me haga bien'],habit:'Caminar un poco',unit:'minutos',target:10,step:5},aprendizaje:{title:'Aprender algo nuevo',why:'Dar espacio a mi curiosidad y crecer a mi ritmo.',steps:['Elegir qué quiero aprender','Reservar 25 minutos para empezar'],habit:'Leer y aprender',unit:'minutos',target:15,step:5},finanzas:{title:'Ordenar mis finanzas',why:'Entender mis gastos y tomar decisiones con tranquilidad.',steps:['Anotar mis gastos habituales','Definir una cantidad posible para ahorrar'],habit:'Revisar mis gastos',unit:'veces',target:1,step:1}};
function applyTemplate(key){const t=templates[key];if(!t)return;const id=uid(),day=today();if(commit(s=>{s.goals.push({id,title:t.title,why:t.why,area:key,deadline:'',created:day});for(const title of t.steps)s.tasks.push({id:uid(),title,goalId:id,date:day,minutes:25,priority:2,status:'todo',created:day,completed:''});s.habits.push({id:uid(),title:t.habit,area:key,target:t.target,targets:[{from:day,value:t.target}],step:t.step,unit:t.unit,logs:{},created:day});},'Tu punto de partida está listo. Puedes editarlo todo.'))render();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;
 if(action==='toggle-weekday'){const selected=el.getAttribute('aria-pressed')!=='true';el.setAttribute('aria-pressed',String(selected));el.classList.toggle('selected',selected);const picker=el.closest('.weekday-picker'),days=[...picker.querySelectorAll('[aria-pressed="true"]')].map(b=>Number(b.dataset.value));picker.querySelector('[data-repeat-summary]').textContent=days.length?'Cada '+days.map(d=>WEEKDAYS[d].toLowerCase()).join(', '):'Una sola vez, en la fecha elegida.';return;}
 if(action==='clear-weekdays'){const picker=el.closest('.weekday-picker');for(const b of picker.querySelectorAll('.weekday-choice')){b.setAttribute('aria-pressed','false');b.classList.remove('selected');}picker.querySelector('[data-repeat-summary]').textContent='Una sola vez, en la fecha elegida.';return;}
 if(action==='restore-task'){if(commit(s=>restoreTask(s,id,el.dataset.day),'Actividad restaurada.'))render();return;}
 if(action==='new-goal-color'){const form=el.closest('form'),color=nextGoalColor([...state.goals,{color:form.elements.color.value}]);form.elements.color.value=color;form.querySelector('.goal-color-swatch').style.background=color;return;}
 if(action==='enable-reminders'){void reminders.enable();return;}
 if(action==='exact-reminders'){void reminders.exact();return;}
 if(action==='reminder-settings'){void reminders.settings();return;}
 if(action==='calendar-month'){calendarMonth=shiftMonth(calendarMonth,Number(el.dataset.offset));selectedDay=calendarMonth+'-01';render();return;}
 if(action==='calendar-today'){selectedDay=today();calendarMonth=selectedDay.slice(0,7);render();return;}
 if(action==='calendar-day'){selectedDay=el.dataset.day;if(selectedDay.slice(0,7)!==calendarMonth)calendarMonth=selectedDay.slice(0,7);render();return;}
 if(action==='update-app'){location.reload();return;}
 if(action==='close-modal')closeModal();else if(action==='new-goal')goalModal();else if(action==='edit-goal')goalModal(id);else if(action==='new-task')taskModal('',el.dataset.goal);else if(action==='edit-task')taskModal(id,'',el.dataset.day);else if(action==='new-habit')habitModal();else if(action==='edit-habit')habitModal(id);else if(action==='settings')settings();else if(action==='about')about();else if(action==='export')exportData();else if(action==='import')$('#import-file').click();else if(action==='pick-day'){if(validDate(el.dataset.day)&&(el.dataset.day<=today()||['hoy','calendario'].includes(route))){selectedDay=el.dataset.day;render();}}else if(action==='toggle-task'){if(commit(s=>{const day=el.dataset.day||selectedDay;if(day>today())return;toggleTask(s,id,day,selectedDay);}))render();}else if(action==='habit-plus'||action==='habit-minus'){if(commit(s=>{const h=s.habits.find(h=>h.id===id);if(!h||!habitScheduled(h,selectedDay)||selectedDay>today())return;h.logs[selectedDay]=Math.max(0,Math.min(1000000,habitValue(h,selectedDay)+h.step*(action==='habit-plus'?1:-1)));}))render();}else if(action==='start-focus')startFocus();else if(action==='start-break')startFocus('','break');else if(action==='focus-task'){startFocus(id);location.hash='enfoque';}else if(action==='pause-focus'){if(commit(s=>{if(!s.timer)return;s.timer.remaining=timerRemaining(s.timer);s.timer.running=false;}))render();}else if(action==='resume-focus'){if(commit(s=>{if(!s.timer)return;s.timer.endAt=Date.now()+s.timer.remaining;s.timer.running=true;}))render();}else if(action==='finish-focus')finishTimer(true);else if(action==='plan')plan();else if(action==='apply-plan'){const ids=el.dataset.ids.split(',');if(commit(s=>{for(const t of s.tasks)if(ids.includes(t.id)){t.priority=3;if(!isRepeating(t))setTaskSchedule(t,selectedDay,[],today());}},'Tus prioridades están listas. Un paso a la vez.')){closeModal();render();}}else if(action==='template')applyTemplate(el.dataset.key);else if(action==='delete-goal')confirmDelete('goal',id);else if(action==='delete-task')confirmDelete('task',id,el.dataset.day||selectedDay);else if(action==='delete-habit')confirmDelete('habit',id);else if(action==='confirm-delete'){if(commit(s=>{const kind=el.dataset.kind;if(kind==='goal'){s.goals=s.goals.filter(g=>g.id!==id);for(const t of s.tasks)if(t.goalId===id)t.goalId='';}if(kind==='task')deleteTask(s,id,el.dataset.day||selectedDay,el.dataset.series==='true');if(kind==='habit')s.habits=s.habits.filter(h=>h.id!==id);},'Eliminado.')){closeModal();render();}}else if(action==='confirm-import'){try{const incoming=JSON.parse($('#modal').dataset.import);ensureGoalColors(incoming);const previous=JSON.stringify(state);localStorage.setItem(KEY+'-antes-de-importar',previous);localStorage.setItem(KEY,JSON.stringify(incoming));state=incoming;reminders?.sync(true);storageBlocked=false;rawRecovery='';$('#storage-warning').hidden=true;closeModal();render();notify('Respaldo importado.');}catch{notify('No pudimos importar. Los datos anteriores se conservan.');}}
});
document.addEventListener('submit',e=>{if(!e.target.matches('form'))return;e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));for(const key of Object.keys(values))values[key]=values[key].trim();const id=form.dataset.id;
 if(form.id==='profile-form'){if(commit(s=>{s.profile={name:values.name,purpose:values.purpose};},'Tu propósito está guardado.')){closeModal();render();}}
 if(form.id==='goal-form'){if(!values.title||!validDate(values.startDate)||values.deadline&&!validDate(values.deadline))return;if(values.deadline&&values.deadline<values.startDate){$('#form-error').textContent='La fecha de fin debe ser igual o posterior al inicio.';return;}if(commit(s=>{const g={id:id||uid(),title:values.title,area:values.area,why:values.why,startDate:values.startDate,deadline:values.deadline,color:values.color,created:today()};const existing=s.goals.find(x=>x.id===id);if(existing)Object.assign(existing,{...g,created:existing.created});else s.goals.push(g);if(!id&&values.firstStep)s.tasks.push({id:uid(),title:values.firstStep,goalId:g.id,date:values.startDate,minutes:25,priority:2,status:'todo',created:today(),completed:''});},'Tu meta tiene un lugar en tu camino.')){closeModal();render();}}
 if(form.id==='task-form'){
  if(!values.title||!validDate(values.date))return;const days=selectedWeekdays(form),durationSeconds=durationFromParts(Number(values.hours),Number(values.minutes||0),Number(values.seconds||0));
  if(!Number.isFinite(durationSeconds)||durationSeconds<1){$('#form-error').textContent='Elige una duración de al menos 1 segundo.';return;}
  if(values.startTime&&!validTime(values.startTime)||values.reminder!=='off'&&!validTime(values.startTime)){$('#form-error').textContent='Elige una hora de inicio para activar el recordatorio.';notify('Elige una hora de inicio para activar el recordatorio.');form.elements.startTime.focus();return;}
  if(commit(s=>{const fields={title:values.title,goalId:values.goalId,priority:Number(values.priority),startTime:values.startTime,reminder:values.reminder,reminderMinutes:Number(values.reminderMinutes),durationSeconds,minutes:durationSeconds/60};const existing=s.tasks.find(t=>t.id===id);if(existing){setTaskSchedule(existing,values.date,days,today());Object.assign(existing,fields);}else s.tasks.push({...fields,id:uid(),date:values.date,repeatDays:days,occurrences:{},status:'todo',created:today(),completed:''});},days.length?'Actividad semanal guardada. Cada día tendrá su propio registro.':'Actividad guardada.')){closeModal();render();}
 }
 if(form.id==='habit-form'){
  if(!values.title||!values.unit)return;const days=selectedWeekdays(form);if(!days.length){$('#form-error').textContent='Selecciona al menos un día de la semana para el hábito.';return;}
  if(commit(s=>{const h=s.habits.find(h=>h.id===id),target=Number(values.target);if(h){h.title=values.title;h.area=values.area;h.unit=values.unit;h.step=Number(values.step);setTarget(h,today(),target);setHabitDays(h,today(),days);}else s.habits.push({id:uid(),title:values.title,area:values.area,unit:values.unit,target,step:Number(values.step),targets:[{from:today(),value:target}],weekDays:days,logs:{},created:today()});},'Hábito y días de la semana guardados.')){closeModal();render();}
 }
 if(form.id==='journal-form'){if(commit(s=>{const entry={day:selectedDay,mood:Number(values.mood),energy:Number(values.energy),wins:values.wins,notes:values.notes};const i=s.journal.findIndex(j=>j.day===selectedDay);if(i>=0)s.journal[i]=entry;else s.journal.push(entry);},'Tu reflexión quedó guardada.'))render();}
});
document.addEventListener('input',e=>{if(e.target.matches('.duration-slider input'))updateDurationPicker(e.target.form);});
document.addEventListener('change',e=>{if(e.target.id==='focus-task-select'){focusTaskId=e.target.value;render();}if(e.target.id==='stats-range'){statsDays=Number(e.target.value);render();}if(e.target.id==='stats-filter'){statsFilter=e.target.value;render();}if(e.target.id==='focus-duration'){focusMinutes=Number(e.target.value);$('#timer-display').textContent=timerDisplay();}if(e.target.id==='day-picker'&&validDate(e.target.value)&&e.target.value<=today()){selectedDay=e.target.value;render();}if(e.target.id==='home-day-picker'&&validDate(e.target.value)){selectedDay=e.target.value;calendarMonth=selectedDay.slice(0,7);render();}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2*1024*1024){notify('El respaldo supera el límite de 2 MB.');return;}try{const incoming=validateBackup(JSON.parse(await file.text()));closeModal();modal('Importar tu camino',`<p class="dialog-note">Este respaldo contiene ${incoming.goals.length} metas, ${incoming.tasks.length} tareas, ${incoming.habits.length} hábitos y ${incoming.journal.length} reflexiones. Reemplazará los datos actuales en este navegador.</p><p class="notice">Descarga primero un respaldo de tus datos actuales si quieres conservarlos.</p><div class="form-actions">${btn('export','Respaldar actuales','','ghost')}${btn('confirm-import','Reemplazar e importar')}</div>`);$('#modal').dataset.import=JSON.stringify(incoming);}catch(e){notify('No pudimos leer el respaldo: el formato es inválido.');}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const raw=JSON.parse(e.newValue);state=validateBackup(raw);state.timer=restoreTimer(raw.timer);ensureGoalColors(state);reminders?.sync();if(!$('#modal').open)render();notify('Datos actualizados desde otra pestaña.');}catch{notify('Otra pestaña guardó datos que no pudimos leer.');}}});
setInterval(()=>{if(state.timer?.running&&timerRemaining(state.timer)===0){finishTimer();return;}const display=$('#timer-display');if(display)display.textContent=timerDisplay();const elapsed=$('#timer-elapsed');if(elapsed&&state.timer)elapsed.textContent=timerElapsed();},250);
reminders=createReminders({getState:()=>state,onStatus:()=>{for(const panel of document.querySelectorAll('[data-reminder-panel]'))panel.innerHTML=reminderPanelContent();},onDue:event=>notify(`${timeLabel(event.task.startTime)} · ${event.task.title}: es hora de tu rutina.`)});
window.addEventListener('life-reminder-open',e=>{selectedDay=validDate(e.detail?.day)?e.detail.day:today();calendarMonth=selectedDay.slice(0,7);location.hash='calendario';render();});
render();if(state.timer?.running&&timerRemaining(state.timer)===0)finishTimer();
if(!window.proyectoAndroid&&'serviceWorker'in navigator){
 const hadController=!!navigator.serviceWorker.controller;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&!document.querySelector('.update-notice')){const notice=document.createElement('div');notice.className='update-notice';notice.setAttribute('role','status');notice.innerHTML='Hay una versión nueva de Proyecto de vida. Tus datos se conservarán. '+btn('update-app','Actualizar');document.querySelector('.topbar').insertAdjacentElement('afterend',notice);}});
 navigator.serviceWorker.register('./sw.js').catch(()=>{});
}
